/**
 * Pure MIDI parsing and relative-jog decoding helpers.
 * Kept free of browser APIs so it can be unit-tested in Node.
 */

export const STATUS_NAMES = {
  0x80: 'NOTE OFF',
  0x90: 'NOTE ON',
  0xa0: 'AFTERTOUCH',
  0xb0: 'CC',
  0xc0: 'PROGRAM',
  0xd0: 'CH PRESSURE',
  0xe0: 'PITCH BEND'
}

const clamp = (v, min, max) => Math.max(min, Math.min(max, v))

/**
 * Parse a raw Web MIDI message into a friendly object.
 * @param {Uint8Array|number[]} input raw message bytes
 * @returns {null|object}
 */
export function parseMidiMessage(input) {
  if (!input) return null
  const data = input instanceof Uint8Array ? input : Array.from(input)
  if (!data.length) return null

  const status = data[0]
  if (status < 0x80) return null // running status is not used by Web MIDI
  const type = status & 0xf0
  const channel = status & 0x0f
  const raw = Array.from(data)
  const base = { channel, channelNumber: channel + 1, status, raw }

  switch (type) {
    case 0x80:
      if (data.length < 3) return null
      return { ...base, type: 'noteoff', note: data[1], velocity: data[2], number: data[1], value: data[2], pressed: false }
    case 0x90: {
      if (data.length < 3) return null
      const velocity = data[2]
      return {
        ...base,
        type: velocity === 0 ? 'noteoff' : 'noteon',
        note: data[1],
        velocity,
        number: data[1],
        value: velocity,
        pressed: velocity > 0
      }
    }
    case 0xa0:
      if (data.length < 3) return null
      return { ...base, type: 'aftertouch', note: data[1], pressure: data[2], number: data[1], value: data[2] }
    case 0xb0:
      if (data.length < 3) return null
      return {
        ...base,
        type: 'cc',
        controller: data[1],
        number: data[1],
        value: data[2],
        unit: data[2] / 127
      }
    case 0xc0:
      if (data.length < 2) return null
      return { ...base, type: 'program', program: data[1], number: data[1], value: data[1] }
    case 0xd0:
      if (data.length < 2) return null
      return { ...base, type: 'channelpressure', pressure: data[1], number: data[1], value: data[1] }
    case 0xe0: {
      if (data.length < 3) return null
      const lsb = data[1]
      const msb = data[2]
      const value = ((msb << 7) | lsb) - 8192
      return { ...base, type: 'pitchbend', number: 0, value, unit: value / 8192, lsb, msb }
    }
    case 0xf0:
      return { ...base, type: data[0] === 0xf8 ? 'clock' : 'sysex', raw }
    default:
      return null
  }
}

/**
 * Decode a 7-bit relative-jog value into a signed tick delta.
 *
 * Modes:
 *  - auto/twos : 0..63 = clockwise, 64..127 = counter-clockwise (7-bit two's complement)
 *  - signed    : 1..63 = positive, 65..127 = negative, 64 = 0
 *  - offset    : value - 64 (0 = -64 ... 127 = +63)
 *  - absolute  : shortest wrap-around delta from the previous absolute value
 *  - absolute0 : raw value difference from previous absolute value (no wrap)
 *
 * @param {number} value incoming 0..127 value
 * @param {string} mode decoding mode
 * @param {number|null} lastValue previous raw value (for absolute modes)
 * @returns {number} signed tick delta
 */
export function decodeRelative(value, mode = 'auto', lastValue = null) {
  const v = clamp(Math.round(Number(value) || 0), 0, 127)
  switch (mode) {
    case 'offset':
      return v - 64
    case 'signed':
      if (v === 64) return 0
      return v < 64 ? v : v - 128
    case 'absolute': {
      if (lastValue === null || lastValue === undefined) return 0
      let delta = v - clamp(Math.round(Number(lastValue) || 0), 0, 127)
      if (delta > 64) delta -= 128
      if (delta < -64) delta += 128
      return delta
    }
    case 'absolute0': {
      if (lastValue === null || lastValue === undefined) return 0
      return v - clamp(Math.round(Number(lastValue) || 0), 0, 127)
    }
    case 'twos':
    case 'auto':
    default:
      return v >= 64 ? v - 128 : v
  }
}

/** Normalise a 7-bit fader to 0..1 */
export function midiUnit(value) {
  return clamp(Number(value) || 0, 0, 127) / 127
}

/** Normalise a pitch-bend message to -1..1 */
export function pitchBendUnit(message) {
  if (!message) return 0
  if (typeof message.unit === 'number') return clamp(message.unit, -1, 1)
  return clamp((Number(message.value) || 0) / 8192, -1, 1)
}

/** Human-readable binding, e.g. "CH 1 · CC 33" */
export function formatBinding(binding) {
  if (!binding) return '—'
  const ch = binding.channel === null || binding.channel === undefined ? 'ANY' : `CH ${binding.channel + 1}`
  if (binding.type === 'cc') return `${ch} · CC ${binding.number}`
  if (binding.type === 'note') return `${ch} · NOTE ${binding.number}`
  if (binding.type === 'pitchbend') return `${ch} · PITCH BEND`
  return `${ch} · ${String(binding.type).toUpperCase()}`
}

/** Short label for the monitor */
export function describeMidiMessage(message) {
  if (!message) return '—'
  const ch = `CH${message.channel + 1}`
  switch (message.type) {
    case 'noteon':
      return `${ch} NOTE ON  ${message.note}  VEL ${message.velocity}`
    case 'noteoff':
      return `${ch} NOTE OFF ${message.note}`
    case 'cc':
      return `${ch} CC ${message.controller}  ${message.value}`
    case 'pitchbend':
      return `${ch} PITCH BEND  ${message.value > 0 ? '+' : ''}${message.value}`
    case 'aftertouch':
      return `${ch} AFTERTOUCH ${message.note} ${message.pressure}`
    case 'channelpressure':
      return `${ch} PRESSURE ${message.value}`
    case 'program':
      return `${ch} PROGRAM ${message.program}`
    default:
      return `${ch} ${message.type.toUpperCase()}`
  }
}

/** Audio analysis helpers: waveform peaks, duration formatting, BPM estimation. */

export function clamp(v, min, max) {
  return Math.max(min, Math.min(max, v))
}

export function formatTime(seconds, forceHours = false) {
  if (!Number.isFinite(seconds) || seconds < 0) seconds = 0
  const total = Math.floor(seconds)
  const h = Math.floor(total / 3600)
  const m = Math.floor((total % 3600) / 60)
  const s = total % 60
  if (h > 0 || forceHours) return `${h}:${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`
  return `${m}:${String(s).padStart(2, '0')}`
}

export function formatBpm(bpm) {
  if (!Number.isFinite(bpm) || bpm <= 0) return '—'
  return bpm.toFixed(1)
}

/**
 * Build min/max-style mono peak data (absolute peak per bucket) for waveform drawing.
 * We keep separate L/R peaks so the waveform can show a proper stereo shape.
 */
export function computePeaks(buffer, buckets = 4096) {
  const left = buffer.getChannelData(0)
  const right = buffer.numberOfChannels > 1 ? buffer.getChannelData(1) : left
  const length = left.length
  const outL = new Float32Array(buckets)
  const outR = new Float32Array(buckets)
  const step = length / buckets
  for (let b = 0; b < buckets; b++) {
    const start = Math.floor(b * step)
    const end = Math.min(length, Math.max(start + 1, Math.floor((b + 1) * step)))
    let maxL = 0
    let maxR = 0
    // Sample at most a few thousand points per bucket; peaks are sparse enough.
    const stride = Math.max(1, Math.floor((end - start) / 512))
    for (let i = start; i < end; i += stride) {
      const l = left[i] < 0 ? -left[i] : left[i]
      const r = right[i] < 0 ? -right[i] : right[i]
      if (l > maxL) maxL = l
      if (r > maxR) maxR = r
    }
    outL[b] = maxL
    outR[b] = maxR
  }
  return { left: outL, right: outR, buckets, duration: buffer.duration }
}

/**
 * Lightweight tempo estimation suitable for dropped MP3s.
 * Builds a 100 Hz energy envelope, runs autocorrelation over 60-200 BPM,
 * folds the result into a useful DJ range and returns a confidence value.
 */
export function estimateBpm(buffer) {
  try {
    const sampleRate = buffer.sampleRate
    const channel = buffer.getChannelData(0)
    const maxSamples = Math.min(channel.length, Math.floor(sampleRate * 60))
    const hop = Math.max(64, Math.floor(sampleRate / 100))
    const frames = Math.floor((maxSamples - hop) / hop)
    if (frames < 120) return { bpm: 0, confidence: 0 }

    const energy = new Float32Array(frames)
    for (let f = 0; f < frames; f++) {
      const start = f * hop
      let sum = 0
      for (let i = start; i < start + hop; i += 2) {
        const s = channel[i] || 0
        sum += s * s
      }
      energy[f] = Math.sqrt(sum / (hop / 2))
    }

    const onset = new Float32Array(frames)
    let mean = 0
    for (let f = 1; f < frames; f++) {
      const a = Math.log1p(energy[f] * 800)
      const b = Math.log1p(energy[f - 1] * 800)
      const d = Math.max(0, a - b)
      onset[f] = d
      mean += d
    }
    mean /= Math.max(1, frames - 1)

    let best = { bpm: 0, score: 0 }
    // 30..100 frames at 10 ms = 60..200 BPM
    for (let lag = 30; lag <= 100; lag++) {
      let cross = 0
      let e1 = 0
      let e2 = 0
      for (let i = lag; i < frames; i++) {
        const a = onset[i] - mean
        const b = onset[i - lag] - mean
        cross += a * b
        e1 += a * a
        e2 += b * b
      }
      const corr = cross / Math.sqrt(e1 * e2 + 1e-9)
      const bpm = 60 / (lag * 0.01)
      // Gentle preference for 100-140 BPM to avoid half/double-time confusion.
      const prior = Math.exp(-Math.pow(Math.log(bpm / 120), 2) / 0.18)
      const score = corr * prior
      if (score > best.score) best = { bpm, score }
    }

    let bpm = best.bpm
    if (!bpm) return { bpm: 0, confidence: 0 }
    while (bpm < 80) bpm *= 2
    while (bpm > 160) bpm /= 2
    return { bpm: Math.round(bpm * 10) / 10, confidence: Math.max(0, best.score) }
  } catch {
    return { bpm: 0, confidence: 0 }
  }
}

export function makePeaksFromArray(left, sampleRate, buckets = 4096) {
  const fake = {
    numberOfChannels: 1,
    sampleRate,
    duration: left.length / sampleRate,
    getChannelData: () => left
  }
  return computePeaks(fake, buckets)
}

import { computePeaks } from './analysis.js'

/** Deterministic RNG so every reload sounds identical. */
function mulberry32(seed) {
  let a = seed >>> 0
  return function () {
    a |= 0
    a = (a + 0x6d2b79f5) | 0
    let t = Math.imul(a ^ (a >>> 15), 1 | a)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

const MINOR = [0, 2, 3, 5, 7, 8, 10]
const MAJOR = [0, 2, 4, 5, 7, 9, 11]

const midiToFreq = (note) => 440 * Math.pow(2, (note - 69) / 12)

export const DEMO_SPECS = [
  {
