    tag: 'ELECTRO'
  }
]

function addKick(left, right, sampleRate, time, amp, rng) {
  const length = Math.min(left.length - Math.floor(time * sampleRate), Math.floor(sampleRate * 0.26))
  if (length <= 0) return
  const start = Math.floor(time * sampleRate)
  let phase = 0
  for (let i = 0; i < length; i++) {
    const t = i / sampleRate
    const freq = 46 + 135 * Math.exp(-t * 34)
    phase += (Math.PI * 2 * freq) / sampleRate
    const env = Math.exp(-t * 15) * (1 - Math.exp(-t * 600))
    let s = Math.sin(phase) * env * amp
    if (i < 90) s += (rng() * 2 - 1) * 0.12 * (1 - i / 90)
    left[start + i] += s
    right[start + i] += s
  }
}

function addNoise(left, right, sampleRate, time, duration, amp, decay, rng, pan = 0, hp = 0.86) {
  const length = Math.min(left.length - Math.floor(time * sampleRate), Math.floor(sampleRate * duration))
  if (length <= 0) return
  const start = Math.floor(time * sampleRate)
  const pl = Math.cos(((pan + 1) * Math.PI) / 4)
  const pr = Math.sin(((pan + 1) * Math.PI) / 4)
  let prev = 0
  for (let i = 0; i < length; i++) {
    const t = i / sampleRate
    const white = rng() * 2 - 1
    const filtered = white - prev * hp
    prev = white
    const env = Math.exp(-t * decay) * (1 - Math.exp(-t * 2500))
    const s = filtered * env * amp
    left[start + i] += s * pl
    right[start + i] += s * pr
  }
}

function addClap(left, right, sampleRate, time, amp, rng) {
  const bursts = [0, 0.011, 0.023, 0.038]
  for (let b = 0; b < bursts.length; b++) {
    addNoise(left, right, sampleRate, time + bursts[b], 0.16, amp * (b === 3 ? 1 : 0.55), 34, rng, 0, 0.55)
  }
}

function addHat(left, right, sampleRate, time, amp, rng, open = false, pan = 0) {
  addNoise(left, right, sampleRate, time, open ? 0.22 : 0.065, amp, open ? 12 : 46, rng, pan, 0.94)
}

function addTone(left, right, sampleRate, time, duration, freq, amp, opts = {}) {
  const length = Math.min(left.length - Math.floor(time * sampleRate), Math.floor(sampleRate * duration))
  if (length <= 0) return
  const start = Math.floor(time * sampleRate)
  const pan = opts.pan || 0
  const pl = Math.cos(((pan + 1) * Math.PI) / 4)
  const pr = Math.sin(((pan + 1) * Math.PI) / 4)
  const harmonics = opts.harmonics || [1, 0.28, 0.12]
  const attack = opts.attack || 0.008
  const release = opts.release || 0.08
  const decay = opts.decay || 0
  let phase = 0
  for (let i = 0; i < length; i++) {
    const t = i / sampleRate
    const envAttack = Math.min(1, t / attack)
    const envRelease = Math.min(1, Math.max(0, (duration - t) / release))
    const envDecay = decay ? Math.exp(-t * decay) : 1
    const env = envAttack * envRelease * envDecay
    phase += (Math.PI * 2 * freq) / sampleRate
    let s = 0
    for (let h = 0; h < harmonics.length; h++) {
      s += Math.sin(phase * (h + 1)) * harmonics[h]
    }
    s *= env * amp
    left[start + i] += s * pl
    right[start + i] += s * pr
  }
}

function addPad(left, right, sampleRate, time, duration, freqs, amp, rng) {
  for (let n = 0; n < freqs.length; n++) {
    const detune = (rng() - 0.5) * 0.6
    addTone(left, right, sampleRate, time, duration, freqs[n] * Math.pow(2, detune / 1200), amp, {
      attack: duration * 0.16,
      release: duration * 0.28,
      pan: (n - 1) * 0.28,
      harmonics: [1, 0.16, 0.07]
    })
  }
}

function renderDemo(spec, sampleRate) {
  const rng = mulberry32(spec.seed)
  const beat = 60 / spec.bpm
  const bars = 16
  const beatsPerBar = 4
  const duration = bars * beatsPerBar * beat
  const length = Math.ceil((duration + 0.15) * sampleRate)
  const left = new Float32Array(length)
  const right = new Float32Array(length)
  const style = spec.style
  const scale = spec.scale

  const noteAt = (degree, octave = 0) => {
    const idx = ((degree % 7) + 7) % 7
    const oct = Math.floor(degree / 7) + octave
    return spec.root + scale[idx] + oct * 12
  }

  const bassPatterns = {
    house: [0, 0, 12, 0, 0, 0, 7, 12],
    tech: [0, 0, 0, 12, 0, 7, 0, 10],
    melodic: [0, 0, 7, 0, 12, 0, 7, 4],
    electro: [0, 0, 12, 7, 0, 0, 14, 7]
  }
  const arpPatterns = {
    house: [0, 2, 4, 6, 4, 2, 7, 4],
    tech: [0, 4, 2, 6, 0, 7, 4, 2],
    melodic: [0, 4, 2, 6, 4, 7, 6, 2],
    electro: [0, 2, 7, 4, 6, 2, 4, 7]
  }
  const bassPattern = bassPatterns[style] || bassPatterns.house
  const arpPattern = arpPatterns[style] || arpPatterns.house

  for (let bar = 0; bar < bars; bar++) {
    const barStart = bar * beatsPerBar * beat
    const chordDegree = spec.progression[bar % spec.progression.length]
    const chordRootMidi = noteAt(chordDegree, 0)
    const chordNotes = [0, 2, 4, 6].map((step) => midiToFreq(noteAt(chordDegree + step, 0) + 12))

    // Kick: four-on-the-floor with a pickup on the final bar.
    for (let b = 0; b < beatsPerBar; b++) {
      const swing = b === 3 && bar % 8 === 7 ? 0.01 : 0
      addKick(left, right, sampleRate, barStart + b * beat + swing, b === 0 ? 0.92 : 0.82, rng)
    }

    // Clap / snare on 2 and 4.
    addClap(left, right, sampleRate, barStart + beat, 0.22, rng)
    addClap(left, right, sampleRate, barStart + 3 * beat, 0.26, rng)

    // Hats: offbeat eighths, with extra 16ths on tech/electro.
    for (let eighth = 0; eighth < 8; eighth++) {
      const t = barStart + eighth * beat * 0.5
      const open = eighth === 3 || eighth === 7
      addHat(left, right, sampleRate, t, open ? 0.1 : 0.075, rng, open, (eighth % 2 ? 1 : -1) * 0.22)
      if ((style === 'tech' || style === 'electro') && eighth % 2 === 1) {
        addHat(left, right, sampleRate, barStart + (eighth + 0.5) * beat * 0.5, 0.045, rng, false, 0.35)
      }
    }

    // Bass groove, one note per eighth.
    for (let step = 0; step < 8; step++) {
      if (style === 'melodic' && (step === 2 || step === 6)) continue
      const semis = bassPattern[step]
      const freq = midiToFreq(chordRootMidi - 12 + semis)
      addTone(left, right, sampleRate, barStart + step * beat * 0.5, beat * 0.42, freq, 0.34, {
        attack: 0.006,
        release: 0.05,
        pan: 0,
        harmonics: [1, 0.22, 0.08]
      })
    }

    // Warm pad / chord bed.
    addPad(left, right, sampleRate, barStart, beat * 4, chordNotes, style === 'melodic' ? 0.075 : 0.055, rng)

    // Chord stabs on the offbeat for house/tech.
    if (style !== 'melodic') {
      for (let stab = 0; stab < 4; stab++) {
        const t = barStart + (stab + 0.5) * beat
        for (let n = 0; n < 3; n++) {
          addTone(left, right, sampleRate, t, beat * 0.22, chordNotes[n] * 2, 0.035, {
            attack: 0.005,
            decay: 22,
            release: 0.04,
            pan: (n - 1) * 0.4,
            harmonics: [1, 0.3]
          })
        }
      }
    }

    // Arp sparkle.
    for (let step = 0; step < 16; step++) {
      const density = style === 'melodic' ? 6 : 10
      if ((step + bar) % 16 > density) continue
      const degree = chordDegree + arpPattern[step % arpPattern.length]
      const freq = midiToFreq(noteAt(degree, 2))
      addTone(left, right, sampleRate, barStart + step * beat * 0.25, beat * 0.18, freq, 0.035, {
        attack: 0.004,
        decay: 30,
        release: 0.03,
        pan: step % 2 ? 0.55 : -0.55,
        harmonics: [1, 0.2]
      })
    }

    // Noise sweep into every 8-bar phrase.
    if (bar % 8 === 7) {
      addNoise(left, right, sampleRate, barStart + 2 * beat, beat * 2, 0.06, 1.5, rng, 0, 0.7)
    }
  }

  // Normalise and gently saturate.
  let peak = 0
  for (let i = 0; i < length; i++) {
    const l = Math.abs(left[i])
    const r = Math.abs(right[i])
    if (l > peak) peak = l
    if (r > peak) peak = r
  }
  const gain = peak > 0.0001 ? 0.9 / peak : 1
  const fade = Math.floor(sampleRate * 0.012)
  for (let i = 0; i < length; i++) {
    const edge = Math.min(1, i / fade, (length - 1 - i) / fade)
    left[i] = Math.tanh(left[i] * gain * 1.05) * 0.94 * edge
    right[i] = Math.tanh(right[i] * gain * 1.05) * 0.94 * edge
  }

  return { left, right, duration }
}

export async function buildDemoTracks(sampleRate, onProgress) {
  const tracks = []
  for (let i = 0; i < DEMO_SPECS.length; i++) {
    const spec = DEMO_SPECS[i]
    onProgress?.(spec, i)
    // Yield so the loading state can paint between renders.
    await new Promise((resolve) => setTimeout(resolve, 0))
    const rendered = renderDemo(spec, sampleRate)
    const buffer = {
      numberOfChannels: 2,
      sampleRate,
      length: rendered.left.length,
      duration: rendered.duration,
      _left: rendered.left,
      _right: rendered.right,
      getChannelData(channel) {
        return channel === 0 ? this._left : this._right
      }
    }
    const peaks = computePeaks(buffer, 4096)
    tracks.push({
      id: spec.id,
      title: spec.title,
      artist: spec.artist,
      bpm: spec.bpm,
      key: spec.key,
      tag: spec.tag,
      color: spec.color,
      color2: spec.color2,
      duration: rendered.duration,
      buffer,
      peaks,
      source: 'demo'
    })
  }
  return tracks
}

/**
 * DeckProcessor — sample-accurate, bidirectional playback engine.
 *
 * A single AudioBufferSourceNode cannot be reliably played backwards across
 * browsers, so this worklet owns the track data and moves an interpolated
 * read-head at a signed rate. That is what makes real jog-wheel scratching
 * (including reverse) work.
 */
class DeckProcessor extends AudioWorkletProcessor {
  constructor() {
    super()
    this.channels = null
    this.length = 0
    this.sourceRate = sampleRate
    this.position = 0 // in source samples
    this.rate = 0
    this.targetRate = 0
    this.rateSmooth = 0.01
    this.gate = 0
    this.active = false
    this.loop = null
    this.ended = false
    this.framesSinceReport = 0
    this.reportNow = true
    this.port.onmessage = (event) => this.handleMessage(event.data)
  }

  handleMessage(message) {
    if (!message) return
    switch (message.type) {
      case 'load': {
        this.channels = message.channels
        this.length = message.length || (this.channels[0] ? this.channels[0].length : 0)
        this.sourceRate = message.sourceRate || sampleRate
        this.position = 0
        this.rate = 0
        this.targetRate = 0
        this.gate = 0
        this.active = false
        this.loop = null
        this.ended = false
        this.reportNow = true
        break
      }
      case 'play': {
        if (typeof message.position === 'number') this.position = this.secondsToSamples(message.position)
        this.active = true
        this.ended = false
        this.reportNow = true
        break
      }
      case 'rate': {
        if (typeof message.value === 'number') this.targetRate = message.value
        if (typeof message.smooth === 'number' && message.smooth > 0) this.rateSmooth = message.smooth
        if (typeof message.active === 'boolean') this.active = message.active
        break
      }
      case 'pause': {
        this.active = false
        this.targetRate = 0
        this.rateSmooth = 0.025
        this.reportNow = true
        break
      }
      case 'active': {
        this.active = Boolean(message.active)
        if (!this.active) this.targetRate = 0
        break
      }
      case 'seek': {
        if (typeof message.position === 'number') this.position = this.secondsToSamples(message.position)
        this.ended = false
        this.reportNow = true
        break
      }
      case 'loop': {
        if (message.enabled && message.end > message.start) {
          this.loop = {
            start: this.secondsToSamples(message.start),
            end: this.secondsToSamples(message.end)
          }
          if (this.loop.end - this.loop.start < this.sourceRate * 0.02) this.loop = null
        } else {
          this.loop = null
        }
        this.reportNow = true
        break
      }
      default:
        break
    }
  }

  secondsToSamples(seconds) {
    return Math.max(0, seconds * this.sourceRate)
  }

  process(_inputs, outputs) {
    const output = outputs[0]
    const left = output[0]
    const right = output[1] || output[0]
    left.fill(0)
    if (output[1]) output[1].fill(0)
    if (!this.channels || !this.length) return true
    if (!this.active && this.gate < 0.0002) {
      this.reportIfNeeded(left.length)
      return true
    }

    const channelL = this.channels[0]
    const channelR = this.channels[1] || this.channels[0]
    const rateCoef = 1 - Math.exp(-1 / (sampleRate * Math.max(0.001, this.rateSmooth)))
    const gateCoef = 1 - Math.exp(-1 / (sampleRate * 0.007))
    const stepScale = this.sourceRate / sampleRate
    const maxIndex = this.length - 2

    for (let i = 0; i < left.length; i++) {
      this.rate += (this.targetRate - this.rate) * rateCoef
      const gateTarget = this.active && Math.abs(this.rate) > 0.0018 ? 1 : 0
      this.gate += (gateTarget - this.gate) * gateCoef

      if (this.active && Math.abs(this.rate) > 0.00001 && this.length > 2 && maxIndex > 0) {
        this.position += this.rate * stepScale

        if (this.loop) {
          const loopLength = this.loop.end - this.loop.start
          if (loopLength > 8) {
            while (this.position >= this.loop.end) this.position -= loopLength
            while (this.position < this.loop.start) this.position += loopLength
          }
        } else if (this.position >= maxIndex) {
          this.position = maxIndex
          this.targetRate = 0
          this.active = false
          if (!this.ended) {
            this.ended = true
            this.port.postMessage({ type: 'ended' })
          }
        } else if (this.position < 0) {
          this.position = 0
          this.targetRate = 0
          this.active = false
          if (!this.ended) {
            this.ended = true
            this.port.postMessage({ type: 'ended' })
          }
        }
      }

      if (this.gate > 0.00005 && maxIndex > 0) {
        const index = this.position | 0
        const frac = this.position - index
        const i0 = index >= 0 ? index : 0
        const i1 = i0 + 1 <= maxIndex ? i0 + 1 : maxIndex
        const l = channelL[i0] + (channelL[i1] - channelL[i0]) * frac
        const r = channelR[i0] + (channelR[i1] - channelR[i0]) * frac
        left[i] = l * this.gate
        if (output[1]) right[i] = r * this.gate
      }
    }

    this.reportIfNeeded(left.length)
    return true
  }

  reportIfNeeded(frames) {
    this.framesSinceReport += frames
    if (this.reportNow || this.framesSinceReport >= sampleRate * 0.035) {
      this.framesSinceReport = 0
      this.reportNow = false
      this.port.postMessage({
        type: 'state',
        position: this.sourceRate ? this.position / this.sourceRate : 0,
        rate: this.rate,
        active: this.active,
        gate: this.gate,
        loop: this.loop
          ? { start: this.loop.start / this.sourceRate, end: this.loop.end / this.sourceRate }
          : null
      })
    }
  }
}

registerProcessor('deck-processor', DeckProcessor)

const clamp = (v, min, max) => Math.max(min, Math.min(max, v))

function now() {
  return (typeof performance !== 'undefined' ? performance.now() : Date.now()) / 1000
}

/** One deck's audio graph and transport state. */
export class DeckAudio {
  constructor(ctx, destination, id) {
    this.ctx = ctx
    this.id = id
    this.duration = 0
    this.playing = false
    this.scratching = false
    this.pitch = 1
    this.position = 0
    this.rate = 0
    this.active = false
    this.gate = 0
    this.stateAt = now()
    this.onEnded = null
    this.levelData = null

    this.worklet = new AudioWorkletNode(ctx, 'deck-processor', {
      numberOfInputs: 0,
      numberOfOutputs: 1,
      outputChannelCount: [2]
    })

    this.channel = ctx.createGain()
    this.channel.gain.value = 0.86

    this.eqLow = ctx.createBiquadFilter()
    this.eqLow.type = 'lowshelf'
    this.eqLow.frequency.value = 180
    this.eqLow.gain.value = 0

    this.eqMid = ctx.createBiquadFilter()
    this.eqMid.type = 'peaking'
    this.eqMid.frequency.value = 1100
    this.eqMid.Q.value = 0.9
    this.eqMid.gain.value = 0

    this.eqHigh = ctx.createBiquadFilter()
    this.eqHigh.type = 'highshelf'
    this.eqHigh.frequency.value = 4200
    this.eqHigh.gain.value = 0

    this.filter = ctx.createBiquadFilter()
    this.filter.type = 'lowpass'
    this.filter.frequency.value = 22000
    this.filter.Q.value = 0.8

    this.crossfader = ctx.createGain()
    this.crossfader.gain.value = 0.707

    this.analyser = ctx.createAnalyser()
    this.analyser.fftSize = 512
    this.analyser.smoothingTimeConstant = 0.65
    this.levelData = new Float32Array(this.analyser.fftSize)

    // Echo send: filter -> delay -> feedback loop + wet gain
    this.delay = ctx.createDelay(1.2)
    this.delay.delayTime.value = 0.36
    this.feedback = ctx.createGain()
    this.feedback.gain.value = 0.32
    this.wet = ctx.createGain()
    this.wet.gain.value = 0
    this.echoOn = false

    this.worklet
      .connect(this.channel)
      .connect(this.eqLow)
      .connect(this.eqMid)
      .connect(this.eqHigh)
      .connect(this.filter)
      .connect(this.crossfader)
      .connect(this.analyser)
      .connect(destination)

    this.filter.connect(this.delay)
    this.delay.connect(this.feedback)
    this.feedback.connect(this.delay)
    this.delay.connect(this.wet)
    this.wet.connect(this.crossfader)

    this.worklet.port.onmessage = (event) => {
      const data = event.data
      if (!data) return
      if (data.type === 'state') {
        this.position = data.position
        this.rate = data.rate
        this.active = data.active
        this.gate = data.gate
        this.stateAt = now()
      } else if (data.type === 'ended') {
        this.playing = false
        this.scratching = false
        this.active = false
        if (this.onEnded) this.onEnded()
      }
    }
  }

  load(track) {
    const buffer = track.buffer
    this.duration = track.duration || buffer.duration
    this.position = 0
    this.rate = 0
    this.active = false
    this.playing = false
    this.scratching = false
    this.stateAt = now()

    const copies = []
    const transfer = []
    for (let ch = 0; ch < 2; ch++) {
      const source = buffer.getChannelData(Math.min(ch, buffer.numberOfChannels - 1))
      const copy = new Float32Array(source.length)
      copy.set(source)
      copies.push(copy)
      transfer.push(copy.buffer)
    }
    this.worklet.port.postMessage(
      {
        type: 'load',
        channels: copies,
        length: copies[0].length,
        sourceRate: buffer.sampleRate
      },
      transfer
    )
    this.setEcho(this.echoOn, track.bpm)
  }

  play() {
    if (!this.duration) return
    this.playing = true
    this.scratching = false
    this.active = true
    this.worklet.port.postMessage({ type: 'play', position: this.getPosition() })
    this.worklet.port.postMessage({ type: 'rate', value: this.pitch, smooth: 0.025, active: true })
  }

  pause() {
    this.playing = false
    this.scratching = false
    this.active = false
    this.worklet.port.postMessage({ type: 'pause' })
  }

  seek(position) {
    const p = clamp(position, 0, Math.max(0, this.duration - 0.01))
    this.position = p
    this.stateAt = now()
    this.worklet.port.postMessage({ type: 'seek', position: p })
  }

  setPitch(pitch) {
    this.pitch = clamp(pitch, 0.5, 1.5)
    if (this.playing && !this.scratching) {
      this.worklet.port.postMessage({ type: 'rate', value: this.pitch, smooth: 0.04 })
    }
  }

  beginScratch() {
    this.scratching = true
    this.worklet.port.postMessage({ type: 'active', active: true })
    this.worklet.port.postMessage({ type: 'rate', value: 0, smooth: 0.012 })
  }

  scratchRate(rate, smooth = 0.012) {
    this.scratching = true
    this.worklet.port.postMessage({ type: 'rate', value: clamp(rate, -10, 10), smooth })
  }

  endScratch() {
    this.scratching = false
    if (this.playing) {
      this.worklet.port.postMessage({ type: 'rate', value: this.pitch, smooth: 0.11 })
      this.worklet.port.postMessage({ type: 'active', active: true })
    } else {
      this.worklet.port.postMessage({ type: 'rate', value: 0, smooth: 0.13 })
      setTimeout(() => {
        if (!this.playing && !this.scratching) {
          this.worklet.port.postMessage({ type: 'pause' })
        }
      }, 190)
    }
  }

  nudge(offset) {
    if (!this.playing) return
    this.worklet.port.postMessage({
      type: 'rate',
      value: clamp(this.pitch + offset, -3, 3),
      smooth: 0.015
    })
  }

  endNudge() {
    if (this.playing && !this.scratching) {
      this.worklet.port.postMessage({ type: 'rate', value: this.pitch, smooth: 0.085 })
    }
  }

  setLoop(enabled, start, end) {
    if (!enabled) {
      this.worklet.port.postMessage({ type: 'loop', enabled: false })
      return
    }
    this.worklet.port.postMessage({ type: 'loop', enabled: true, start: Math.max(0, start), end: Math.max(start + 0.05, end) })
  }

  setEQ(band, value) {
    const gain = clamp(value, -1, 1) * 12
    const node = band === 'low' ? this.eqLow : band === 'mid' ? this.eqMid : this.eqHigh
    node.gain.setTargetAtTime(gain, this.ctx.currentTime, 0.02)
  }

  setFilter(value) {
    const v = clamp(value, 0, 1)
    const t = this.ctx.currentTime
    if (v < 0.48) {
      this.filter.type = 'lowpass'
      const frequency = 110 * Math.pow(19000 / 110, v / 0.48)
      this.filter.frequency.setTargetAtTime(frequency, t, 0.02)
    } else if (v > 0.52) {
      this.filter.type = 'highpass'
      const frequency = 20 * Math.pow(9000 / 20, (v - 0.52) / 0.48)
      this.filter.frequency.setTargetAtTime(frequency, t, 0.02)
    } else {
      this.filter.type = 'lowpass'
      this.filter.frequency.setTargetAtTime(22000, t, 0.02)
    }
  }

  setChannelVolume(value) {
    const v = clamp(value, 0, 1)
    this.channel.gain.setTargetAtTime(Math.pow(v, 1.5), this.ctx.currentTime, 0.02)
  }

  setCrossfaderGain(gain) {
    this.crossfader.gain.setTargetAtTime(gain, this.ctx.currentTime, 0.015)
  }

  setEcho(enabled, bpm) {
    this.echoOn = Boolean(enabled)
    const beat = bpm > 0 ? 60 / bpm : 0.5
    this.delay.delayTime.setTargetAtTime(clamp(beat * 0.75, 0.05, 1.1), this.ctx.currentTime, 0.05)
    this.feedback.gain.setTargetAtTime(enabled ? 0.36 : 0.12, this.ctx.currentTime, 0.02)
    this.wet.gain.setTargetAtTime(enabled ? 0.3 : 0, this.ctx.currentTime, 0.03)
  }

  getPosition() {
    if (!this.duration) return 0
    const elapsed = Math.max(0, now() - this.stateAt)
    let position = this.position
    if (this.active && Math.abs(this.rate) > 0.0001) position += this.rate * elapsed
    return clamp(position, 0, this.duration)
  }

  getRate() {
    return this.rate
  }

  getLevel() {
    if (!this.analyser) return 0
    this.analyser.getFloatTimeDomainData(this.levelData)
    let sum = 0
    for (let i = 0; i < this.levelData.length; i += 2) {
      const sample = this.levelData[i]
      sum += sample * sample
    }
    const rms = Math.sqrt(sum / (this.levelData.length / 2))
    return clamp(Math.pow(rms * 3.4, 0.62), 0, 1)
  }
}

export class AudioEngine {
  constructor() {
    const Context = window.AudioContext || window.webkitAudioContext
    if (!Context) throw new Error('Web Audio is not supported in this browser')
    this.ctx = new Context({ latencyHint: 'interactive' })
    this.master = this.ctx.createGain()
    this.master.gain.value = 0.78
    this.limiter = this.ctx.createDynamicsCompressor()
    this.limiter.threshold.value = -7
    this.limiter.knee.value = 6
    this.limiter.ratio.value = 9
    this.limiter.attack.value = 0.003
    this.limiter.release.value = 0.22
    this.masterAnalyser = this.ctx.createAnalyser()
    this.masterAnalyser.fftSize = 256
    this.masterAnalyser.smoothingTimeConstant = 0.7
    this.masterData = new Float32Array(this.masterAnalyser.fftSize)
    this.master.connect(this.limiter)
    this.limiter.connect(this.masterAnalyser)
    this.masterAnalyser.connect(this.ctx.destination)
    this.decks = {}
    this.crossfaderValue = 0
    this.ready = false
  }

  async init() {
    if (this.ready) return
    await this.ctx.audioWorklet.addModule(new URL('./deck-processor.js', import.meta.url))
    this.decks.A = new DeckAudio(this.ctx, this.master, 'A')
    this.decks.B = new DeckAudio(this.ctx, this.master, 'B')
    this.setCrossfader(0)
    this.ready = true
  }

  async resume() {
    if (this.ctx.state !== 'running') {
      try {
        await this.ctx.resume()
      } catch {
        /* browser still waiting for a gesture */
      }
    }
    return this.ctx.state
  }

  setCrossfader(value) {
    this.crossfaderValue = clamp(value, -1, 1)
    const unit = (this.crossfaderValue + 1) / 2
    const gainA = Math.cos((unit * Math.PI) / 2)
    const gainB = Math.sin((unit * Math.PI) / 2)
    if (this.decks.A) this.decks.A.setCrossfaderGain(gainA)
    if (this.decks.B) this.decks.B.setCrossfaderGain(gainB)
  }

  setMasterVolume(value) {
    const v = clamp(value, 0, 1)
    this.master.gain.setTargetAtTime(Math.pow(v, 1.25), this.ctx.currentTime, 0.02)
  }

  getMasterLevel() {
    this.masterAnalyser.getFloatTimeDomainData(this.masterData)
    let sum = 0
    for (let i = 0; i < this.masterData.length; i += 2) {
      const s = this.masterData[i]
      sum += s * s
    }
    const rms = Math.sqrt(sum / (this.masterData.length / 2))
    return clamp(Math.pow(rms * 3.2, 0.6), 0, 1)
  }

  async decodeFile(file) {
    const arrayBuffer = await file.arrayBuffer()
    return this.ctx.decodeAudioData(arrayBuffer)
  }
}

import { decodeRelative, describeMidiMessage, formatBinding, midiUnit, parseMidiMessage, pitchBendUnit } from './midi-core.js'

