    ui.wizardOverlay.hidden = false
    state.midi.cancelLearn()
    await state.midi.enable()
    runWizard()
  })
  $('#wizardClose').addEventListener('click', closeWizard)
  $('#wizardSkip').addEventListener('click', () => state.midi?.cancelCapture())
