import test from 'node:test'
import assert from 'node:assert/strict'
import { computePeaks, estimateBpm, formatTime } from '../js/analysis.js'

function clickTrack({ sampleRate = 44100, bpm = 120, seconds = 12, duration = 0.06 } = {}) {
  const length = sampleRate * seconds
  const data = new Float32Array(length)
  const beat = 60 / bpm
  let seed = 1234567
  const random = () => {
    seed = (seed * 1664525 + 1013904223) >>> 0
    return (seed / 4294967296) * 2 - 1
  }
  for (let t = 0; t < seconds; t += beat) {
    const start = Math.floor(t * sampleRate)
    const count = Math.floor(duration * sampleRate)
    for (let i = 0; i < count && start + i < length; i++) {
      const env = Math.exp(-(i / sampleRate) * 38)
      data[start + i] += Math.sin((i / sampleRate) * 2 * Math.PI * 70) * env * 0.8 + random() * env * 0.2
    }
  }
  return {
    numberOfChannels: 1,
    sampleRate,
    length,
    duration: seconds,
    getChannelData: () => data
  }
}

test('formats times for DJ displays', () => {
  assert.equal(formatTime(0), '0:00')
  assert.equal(formatTime(65), '1:05')
  assert.equal(formatTime(3661), '1:01:01')
  assert.equal(formatTime(3661, true), '1:01:01')
})

test('computes stereo waveform peaks', () => {
  const buffer = clickTrack()
  const peaks = computePeaks(buffer, 256)
  assert.equal(peaks.buckets, 256)
  assert.equal(peaks.left.length, 256)
  assert.equal(peaks.right.length, 256)
  assert.ok(Math.max(...peaks.left) > 0.5)
})

test('estimates around 120 BPM from a click track', () => {
  const buffer = clickTrack({ bpm: 120, seconds: 20 })
  const result = estimateBpm(buffer)
  assert.ok(result.bpm >= 116 && result.bpm <= 124, `expected ~120 BPM, got ${result.bpm}`)
  assert.ok(result.confidence > 0)
})

import { createRequire } from 'node:module'
import { readFileSync, mkdirSync } from 'node:fs'
import { join } from 'node:path'

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
mkdirSync('/tmp/scratchlab-shots', { recursive: true })

const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
const errors = []
page.on('pageerror', (error) => errors.push(`PAGEERROR: ${error.message}`))
page.on('console', (message) => {
  if (message.type() === 'error') errors.push(`CONSOLE: ${message.text()}`)
})
page.setDefaultTimeout(30000)
await page.goto('http://localhost:3002', { waitUntil: 'load' })
await page.waitForFunction(() => window.scratchlab?.ready === true, null, { timeout: 30000 })
await page.waitForTimeout(1200)
await page.screenshot({ path: '/tmp/scratchlab-shots/desktop-idle.png' })
const idle = await page.evaluate(() => window.scratchlab.snapshot())

await page.locator('#playA').click()
await page.waitForTimeout(1500)
await page.screenshot({ path: '/tmp/scratchlab-shots/desktop-playing.png' })
const playing = await page.evaluate(() => window.scratchlab.snapshot())

// Exercise the actual MIDI parser + relative decoder + scratch engine.
await page.evaluate(() => {
  window.scratchlab.bind('deckA.jog', { type: 'cc', channel: 0, number: 33 })
  window.scratchlab.bind('deckA.touch', { type: 'note', channel: 0, number: 54 })
  window.scratchlab.bind('mixer.crossfader', { type: 'cc', channel: 0, number: 7 })
})
await page.evaluate(() => {
  for (let i = 0; i < 5; i++) window.scratchlab.midiRaw([0xb0, 33, 2])
})
await page.waitForTimeout(300)
await page.evaluate(() => {
  window.scratchlab.midiRaw([0xb0, 7, 0])
  window.scratchlab.midiRaw([0x90, 54, 127])
  for (let i = 0; i < 5; i++) window.scratchlab.midiRaw([0xb0, 33, 126])
  window.scratchlab.midiRaw([0x80, 54, 0])
})
await page.waitForTimeout(500)
const afterMidi = await page.evaluate(() => window.scratchlab.snapshot())
await page.screenshot({ path: '/tmp/scratchlab-shots/desktop-midi.png' })

await page.locator('#midiOpen').click()
await page.waitForTimeout(600)
await page.screenshot({ path: '/tmp/scratchlab-shots/desktop-midi-panel.png' })
await page.locator('[data-close="midiOverlay"]').click()

// Virtual controller path, which feeds the same parser.
await page.evaluate(() => {
  document.querySelector('#virtualToggle').click()
})
await page.waitForTimeout(200)
await page.screenshot({ path: '/tmp/scratchlab-shots/desktop-virtual.png' })

const mobile = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1 })
const mobileErrors = []
mobile.on('pageerror', (error) => mobileErrors.push(error.message))
mobile.on('console', (message) => { if (message.type() === 'error') mobileErrors.push(message.text()) })
await mobile.goto('http://localhost:3002', { waitUntil: 'load' })
await mobile.waitForFunction(() => window.scratchlab?.ready === true, null, { timeout: 30000 })
await mobile.waitForTimeout(900)
await mobile.screenshot({ path: '/tmp/scratchlab-shots/mobile-top.png' })
await mobile.screenshot({ path: '/tmp/scratchlab-shots/mobile-full.png', fullPage: true })
const mobileMetrics = await mobile.evaluate(() => ({
  scrollWidth: document.documentElement.scrollWidth,
  innerWidth: window.innerWidth,
  scrollHeight: document.documentElement.scrollHeight,
  bodyOverflow: getComputedStyle(document.body).overflow,
  deckWidth: document.querySelector('#deckA').getBoundingClientRect().width,
  platterWidth: document.querySelector('#platterA').getBoundingClientRect().width
}))

console.log(JSON.stringify({
  errors,
